import { crc32 } from 'node:zlib'

import type { AspectRatio, MmaPlatform, MmaSeo, SeoReading } from '../../types/mma/mma.types.js'

const MINA_SITE = 'mina.faltastudio.com'
const MINA_URL = `https://${MINA_SITE}`
const MINA_TAGLINE = 'higher intelligence for brands that can’t use AI'
const MINA_CREDIT = `Mina — ${MINA_TAGLINE}`
const MINA_COPYRIGHT = `© Mina · ${MINA_SITE}`

/** After the alt text: "Generated by Mina — higher intelligence for brands that can’t use AI · mina.faltastudio.com". */
const ATTRIBUTION = `Generated by ${MINA_CREDIT} · ${MINA_SITE}`

/** After the description: "AI image · Mina · mina.faltastudio.com". */
const DESCRIPTION_CREDIT = `AI image · Mina · ${MINA_SITE}`

/** The IPTC term Google and Pinterest read to label a picture "AI generated". */
const DIGITAL_SOURCE_TYPE = 'trainedAlgorithmicMedia'

const SEO_STOPWORDS = new Set([
  'the', 'a', 'an', 'and', 'or', 'of', 'to', 'in', 'on', 'with', 'for', 'at', 'by', 'from',
  'is', 'are', 'be', 'this', 'that', 'it', 'its', 'as', 'into', 'onto', 'over', 'under',
  'keep', 'keeps', 'keeping', 'kept', 'same', 'unchanged', 'preserve', 'preserving', 'maintain',
  'edit', 'editing', 'image', 'scene', 'make', 'made', 'add', 'added', 'change', 'changed', 'changing',
  'your', 'my', 'our', 'their', 'his', 'her', 'you', 'we', 'they',
  'very', 'really', 'just', 'also', 'then', 'than', 'but', 'not', 'no',
])

/** What gpt-4o-mini is asked to do with the prompt. */
export const SEO_WRITER_PROMPT =
  'You write factual SEO metadata for a marketing image, from the prompt an image model was given to make it. ' +
  'Describe the picture the prompt produces, not the instructions: ignore edit commands, locks and anything the prompt says to avoid. ' +
  'Return STRICT JSON: {"sentence": one vivid, factual sentence (max 22 words) describing what the image shows — main subject, setting, style, colours — no marketing fluff and no invented brand names; ' +
  '"keywords": 8-14 short lowercase search terms for what the image shows}.'

/** A prompt as plain description: edit commands and "keep … unchanged" filler removed. Ported from the old backend. */
function cleanPromptText(raw: string) {
  let text = raw.replace(/\s+/g, ' ').trim()
  let wasEdit = false

  const opener = /^edit\s+(?:(?:in|on|to|the|this|that|my|your|a|an)\s+)*(scene|image|photo|picture|shot)\b\s*[:,.\-–—]*\s*/i
  if (opener.test(text)) {
    text = text.replace(opener, '')
    wasEdit = true
  }
  if (/^(keep|keeps|keeping|preserve|preserving|maintain|retain)\b/i.test(text) || /\bexactly\s+as\s+(it\s+is|is)\b/i.test(text)) {
    wasEdit = true
  }
  if (wasEdit) {
    text = text.replace(
      /(^|[.!?;,—–-]\s*)(keep|keeps|keeping|preserve|preserving|maintain|retain)\s+(the\s+|this\s+|that\s+|all\s+|everything\s+|its\s+|their\s+)?/gi,
      '$1',
    )
    text = text.replace(/\bexactly\s+(the\s+same|as\s+(it\s+is|is|they\s+are|shown))\b/gi, '')
    text = text.replace(/\b(completely|perfectly|entirely|totally)?\s*unchanged\b/gi, '')
    text = text.replace(/\bsame\s+/gi, '')
  }

  return text
    .replace(/^[\s:,.\-–—]+/, '')
    .replace(/\s{2,}/g, ' ')
    .replace(/\s+([,.;])/g, '$1')
    .replace(/(,\s*){2,}/g, ', ')
    .trim()
}

/** Cut at a word boundary, with an ellipsis, when longer than `max`. */
function truncateText(text: string, max: number) {
  const trimmed = text.trim()
  if (trimmed.length <= max) return trimmed

  const cut = trimmed.slice(0, max - 1)
  const lastSpace = cut.lastIndexOf(' ')

  return `${(lastSpace > max * 0.5 ? cut.slice(0, lastSpace) : cut).trim()}…`
}

function extractKeywords(text: string, limit: number) {
  const words = text.toLowerCase().match(/[a-z][a-z'-]{2,}/g) ?? []

  return [...new Set(words)].filter((word) => !SEO_STOPWORDS.has(word)).slice(0, limit)
}

//THIS METHOD IS FOR CREATING THE MMA SEO METADATA .
export function buildSeo({
  reading,
  prompt,
  passId,
  generationId,
  ratio,
  platform,
}: {
  reading: SeoReading | null
  prompt: string
  passId: string
  generationId: string
  ratio: AspectRatio
  platform: MmaPlatform
}): MmaSeo {
  const sentence = reading?.sentence.replace(/\s+/g, ' ').trim() ?? ''
  const cleaned = cleanPromptText(prompt)
  const core = sentence || truncateText(cleaned, 200) || 'Editorial still-life scene'

  const description = `${truncateText(core, Math.max(40, 160 - DESCRIPTION_CREDIT.length - 3))} — ${DESCRIPTION_CREDIT}`
  const altCore = truncateText(core, Math.max(60, 300 - ATTRIBUTION.length - 3)).replace(/[.!?…]+$/, '')
  const alt = `${altCore}. ${ATTRIBUTION}`

  const keywords: string[] = []
  const add = (word: string) => {
    const term = word.toLowerCase().replace(/\s+/g, ' ').trim()
    if (term.length > 2 && !SEO_STOPWORDS.has(term) && !keywords.includes(term)) keywords.push(term)
  }
  reading?.keywords.forEach(add)
  extractKeywords(core, 14).forEach(add)
  ;['mina', 'faltastudio', 'ai generated', 'ai image', 'image'].forEach(add)

  const capped = keywords.slice(0, 28)

  return {
    alt,
    description,
    keywords: capped,
    source: MINA_SITE,
    generator: 'Mina',
    decidedBy: sentence ? 'vision' : cleaned ? 'prompt' : 'template',
    trace: {
      ratio,
      medium: 'image',
      source: MINA_SITE,
      account: passId,
      platform,
      site_url: MINA_URL,
      generator: 'Mina',
      brand_line: MINA_TAGLINE,
      attribution: ATTRIBUTION,
      ai_generated: true,
      duration_sec: null,
      generation_id: generationId,
      digital_source_type: DIGITAL_SOURCE_TYPE,
    },
    schema: {
      '@type': 'ImageObject',
      creator: { url: MINA_URL, name: 'Mina', '@type': 'Organization' },
      '@context': 'https://schema.org',
      keywords: capped.join(', '),
      creditText: MINA_CREDIT,
      description,
      copyrightNotice: MINA_COPYRIGHT,
      acquireLicensePage: MINA_URL,
    },
  }
}

const escapeXml = (text: string) =>
  text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

/**
 * The XMP packet written into the picture: Mina as creator and copyright
 * holder, the alt text, the keywords and the IPTC "AI generated" tag. The
 * customer's account stays out of the file: it is public on R2.
 */
export function xmpPacket(seo: MmaSeo, url: string) {
  const keywords = seo.keywords.map((keyword) => `<rdf:li>${escapeXml(keyword)}</rdf:li>`).join('')

  return `<?xpacket begin="﻿" id="W5M0MpCehiHzreSzNTczkc9d"?>
<x:xmpmeta xmlns:x="adobe:ns:meta/">
<rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">
<rdf:Description rdf:about=""
 xmlns:dc="http://purl.org/dc/elements/1.1/"
 xmlns:xmp="http://ns.adobe.com/xap/1.0/"
 xmlns:xmpRights="http://ns.adobe.com/xap/1.0/rights/"
 xmlns:photoshop="http://ns.adobe.com/photoshop/1.0/"
 xmlns:Iptc4xmpExt="http://iptc.org/std/Iptc4xmpExt/2008-02-29/"
 xmp:CreatorTool="Mina"
 xmpRights:Marked="True"
 xmpRights:WebStatement="${MINA_URL}"
 photoshop:Credit="${escapeXml(MINA_CREDIT)}"
 photoshop:Source="${MINA_SITE}"
 Iptc4xmpExt:DigitalSourceType="http://cv.iptc.org/newscodes/digitalsourcetype/${DIGITAL_SOURCE_TYPE}">
<dc:creator><rdf:Seq><rdf:li>Mina</rdf:li></rdf:Seq></dc:creator>
<dc:rights><rdf:Alt><rdf:li xml:lang="x-default">${escapeXml(MINA_COPYRIGHT)}</rdf:li></rdf:Alt></dc:rights>
<dc:description><rdf:Alt><rdf:li xml:lang="x-default">${escapeXml(seo.alt)}</rdf:li></rdf:Alt></dc:description>
<dc:title><rdf:Alt><rdf:li xml:lang="x-default">${escapeXml(seo.description)}</rdf:li></rdf:Alt></dc:title>
<dc:subject><rdf:Bag>${keywords}</rdf:Bag></dc:subject>
<dc:source>${escapeXml(url)}</dc:source>
</rdf:Description>
</rdf:RDF>
</x:xmpmeta>
<?xpacket end="w"?>`
}

/** A PNG chunk: length, type, data, and the CRC of type + data. */
function pngChunk(type: string, data: Buffer) {
  const typeAndData = Buffer.concat([Buffer.from(type, 'latin1'), data])
  const length = Buffer.alloc(4)
  const crc = Buffer.alloc(4)
  length.writeUInt32BE(data.length)
  crc.writeUInt32BE(crc32(typeAndData))

  return Buffer.concat([length, typeAndData, crc])
}

/**
 * The picture with the XMP packet written in, without re-encoding a single
 * pixel: an `iTXt` chunk right after a PNG's header, an APP1 segment after a
 * JPEG's start (and its JFIF block, which must stay first).
 */
export function embedXmp(bytes: Buffer, contentType: string, xmp: string) {
  const packet = Buffer.from(xmp, 'utf8')

  if (contentType === 'image/png') {
    // Signature (8) + IHDR chunk (4 length + 4 type + 13 data + 4 CRC).
    const afterHeader = 33
    // Keyword, then compression flag and method (0, 0), empty language tag and translated keyword.
    const data = Buffer.concat([Buffer.from('XML:com.adobe.xmp\0\0\0\0\0', 'latin1'), packet])

    return Buffer.concat([bytes.subarray(0, afterHeader), pngChunk('iTXt', data), bytes.subarray(afterHeader)])
  }

  if (contentType === 'image/jpeg') {
    const header = Buffer.from('http://ns.adobe.com/xap/1.0/\0', 'latin1')
    const segmentLength = Buffer.alloc(2)
    segmentLength.writeUInt16BE(2 + header.length + packet.length)
    const segment = Buffer.concat([Buffer.from([0xff, 0xe1]), segmentLength, header, packet])

    // After the start-of-image marker, and after a JFIF APP0 block when there is one.
    const hasJfif = bytes[2] === 0xff && bytes[3] === 0xe0
    const insertAt = hasJfif ? 4 + bytes.readUInt16BE(4) : 2

    return Buffer.concat([bytes.subarray(0, insertAt), segment, bytes.subarray(insertAt)])
  }

  throw new Error(`Cannot embed metadata in ${contentType}`)
}
